import Foundation
import MeadowFile
import MeadowScene
import Testing
@testable import WhiskrMeadow

// The Default meadow as a file, and meadow files as the scene's scenery. The Default is generated by the
// scene (`MeadowScenery.standard`); its file is locked by a released fixture, so neither can drift.

/// The released meadow files (`MeadowFileTests/Fixtures/MeadowFiles`), read from the source tree: they
/// belong to the format's own tests, and are locked there by their digests.
private func fixture(_ name: String) throws -> Data {
    let folder = URL(fileURLWithPath: #filePath).deletingLastPathComponent().deletingLastPathComponent()
        .appendingPathComponent("MeadowFileTests/Fixtures/MeadowFiles", isDirectory: true)
    return try Data(contentsOf: folder.appendingPathComponent(name))
}

@Suite("Meadow files as the scene's scenery")
struct MeadowSceneryMappingTests {
    @Test("the Default, written as a file, is the released fixture byte for byte")
    func defaultIsTheFixture() throws {
        let written = try MeadowDocument(.standard, name: "Default").fileData(writtenBy: "0.1.0")
        #expect(written == (try fixture("v1-catalog1-default.whiskrmeadow")))
    }

    @Test("the Default's file reads back as the Default: nothing clamped, left out or kept from elsewhere")
    func defaultReadsBack() throws {
        let data = try fixture("v1-catalog1-default.whiskrmeadow")
        let reading = try MeadowDocument.read(data)
        #expect(reading.leftOutside == 0 && reading.newerThings == 0 && !reading.keepsNewerContent)
        #expect(reading.document.readFrom?.needsCatalog == 1)
        // Written again, the same bytes: every value was already within its range.
        var document = reading.document
        document.readFrom = nil
        #expect(try document.fileData(writtenBy: "0.1.0") == data)
        // And drawn, the same things in the same order, to the file's 4 decimals.
        let drawn = MeadowScenery(document).things, standard = MeadowScenery.standard.things
        #expect(drawn.count == standard.count)
        for (a, b) in zip(drawn, standard) {
            #expect(a.id == b.id && a.seed == b.seed && a.variant == b.variant, "\(b.id)")
            let apart = max(abs(a.x - b.x), abs(a.z - b.z), abs(a.size.x - b.size.x), abs(a.size.y - b.size.y), abs(a.size.z - b.size.z),
                            abs(a.tilt.x - b.tilt.x), abs(a.tilt.y - b.tilt.y), abs(remainder(a.turn - b.turn, 2 * .pi)))
            #expect(apart <= 6e-5, "\(b.id) at \(b.x), \(b.z): \(apart)")
        }
    }

    @Test("a document maps to scenery and back unchanged; what the scene cannot draw stays in the document")
    func roundTrip() throws {
        let document = MeadowDocument(name: "Mine", entries: [
            .item(MeadowItem(asset: "tree.birch", placement: .at(MeadowPoint(30, -12.5)), turn: 1.25, size: [1.1, 0.9, 1.05], tilt: [0.02, -0.01], seed: 99)),
            .item(MeadowItem(asset: "flower.poppy", placement: .at(MeadowPoint(-3, 4)), variant: 1)),
            .item(MeadowItem(asset: "cat.box", placement: .at(MeadowPoint(5, 5)))),
            .item(MeadowItem(asset: "garden.fence", placement: .run([MeadowPoint(0, 0), MeadowPoint(3, 0)]))),
            .parcel(MeadowParcel(fields: ["id": .string("water.pond"), "at": .array([.number(1), .number(2)])])),
        ])
        let scenery = MeadowScenery(document)
        #expect(scenery.things.map(\.id) == ["tree.birch", "flower.poppy"])
        #expect(scenery.things[0] == MeadowScenery.Thing(id: "tree.birch", x: 30, z: -12.5, turn: 1.25, size: Vec3(1.1, 0.9, 1.05), tilt: Vec2(0.02, -0.01), seed: 99))
        #expect(scenery.things[1].variant == 1)
        let back = MeadowDocument(scenery, name: "Mine")
        #expect(MeadowScenery(back) == scenery)
        #expect(back.items.map(\.asset) == ["tree.birch", "flower.poppy"])
    }

    /// Catalog ids whose scene builders come in a later stage of the editor, with that stage. Until then
    /// a meadow keeps such things and the picture leaves them out (as it does a thing from a newer
    /// Whiskr); the tray offers only what the scene draws. This list only ever shrinks, and is empty
    /// before catalog 1 is released.
    static let buildersToCome: [String: String] = [
        "stone.boulder": "4", "stone.stepping": "4", "work.cushion": "4",
        "ground.path": "5", "ground.lawn": "5", "ground.soil": "5",
        "tree.apple": "7", "tree.pine": "7", "flower.cornflower": "7", "flower.foxglove": "7", "plant.fern": "7", "plant.clover": "7",
        "wood.stump": "7", "wood.logPile": "7", "cat.box": "7", "cat.scratchingPost": "7", "cat.yarn": "7", "cat.bed": "7", "cat.bowl": "7",
        "garden.fence": "8", "garden.flowerPot": "8", "garden.planter": "8", "garden.wateringCan": "8", "garden.birdhouse": "8",
        "garden.skep": "8", "work.desk": "8", "work.bookshelf": "8", "work.bench": "8", "work.signpost": "8", "work.mailbox": "8",
        "work.noticeboard": "8", "place.shed": "8", "place.tent": "8",
        "work.lampPost": "9",
    ]

    @Test("every catalog id has a scene builder, or is one whose builder is still to come; the scene draws nothing the catalog lacks")
    func everyIdHasABuilder() {
        let catalog = MeadowCatalog.current
        for asset in catalog.assets where asset.nature != .eraser {
            let drawn = asset.nature == .paint ? false : MeadowScenery.draws(asset.id)
            #expect(drawn != (Self.buildersToCome[asset.id] != nil), "\(asset.id): drawn \(drawn), to come \(Self.buildersToCome[asset.id] ?? "no")")
        }
        for id in MeadowScenery.drawnIds { #expect(catalog.asset(id)?.id == id, "\(id) is in the catalog") }
        for id in Self.buildersToCome.keys { #expect(catalog.asset(id) != nil, "\(id)") }
        // The Default needs nothing still to come.
        #expect(MeadowScenery.standard.things.allSatisfy { Self.buildersToCome[$0.id] == nil })
    }

    @Test("the scene draws as much as a meadow file may hold, and no more")
    func limitsAreTheCaps() {
        #expect(MeadowScenery.Limits.things == MeadowFormat.maxItems)
        #expect(MeadowScenery.Limits.trees == MeadowCatalog.Cap.trees.limit)
        #expect(MeadowScenery.Limits.tall == MeadowCatalog.Cap.tall.limit)
        #expect(Double(MeadowScenery.Limits.reach) == MeadowFormat.reach)
    }
}
